// --- mynsdb.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* mynsdb::value_ToCstr(const mynsdb::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case mynsdb_FieldId_part           : ret = "part";  break;
        case mynsdb_FieldId_amt            : ret = "amt";  break;
        case mynsdb_FieldId_comment        : ret = "comment";  break;
        case mynsdb_FieldId_value          : ret = "value";  break;
    }
    return ret;
}

// --- mynsdb.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void mynsdb::value_Print(const mynsdb::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- mynsdb.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool mynsdb::value_SetStrptrMaybe(mynsdb::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('a','m','t'): {
                    value_SetEnum(parent,mynsdb_FieldId_amt); ret = true; break;
                }
            }
            break;
        }
        case 4: {
            switch (u64(algo::ReadLE32(rhs.elems))) {
                case LE_STR4('p','a','r','t'): {
                    value_SetEnum(parent,mynsdb_FieldId_part); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,mynsdb_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 7: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)|(u64(rhs[6])<<48)) {
                case LE_STR7('c','o','m','m','e','n','t'): {
                    value_SetEnum(parent,mynsdb_FieldId_comment); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

