// --- mynsdb.Part..ReadFieldMaybe
bool mynsdb::Part_ReadFieldMaybe(mynsdb::Part& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    mynsdb::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case mynsdb_FieldId_part: {
            retval = algo::Smallstr50_ReadStrptrMaybe(parent.part, strval);
            break;
        }
        case mynsdb_FieldId_amt: {
            retval = i32_ReadStrptrMaybe(parent.amt, strval);
            break;
        }
        case mynsdb_FieldId_comment: {
            retval = algo::Comment_ReadStrptrMaybe(parent.comment, strval);
            break;
        }
        default: break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

// --- mynsdb.Part..ReadStrptrMaybe
// Read fields of mynsdb::Part from an ascii string.
// The format of the string is an ssim Tuple
bool mynsdb::Part_ReadStrptrMaybe(mynsdb::Part &parent, algo::strptr in_str) {
    bool retval = true;
    retval = algo::StripTypeTag(in_str, "mynsdb.part") || algo::StripTypeTag(in_str, "mynsdb.Part");
    ind_beg(algo::Attr_curs, attr, in_str) {
        retval = retval && Part_ReadFieldMaybe(parent, attr.name, attr.value);
    }ind_end;
    return retval;
}

// --- mynsdb.Part..Print
// print string representation of ROW to string STR
// cfmt:mynsdb.Part.String  printfmt:Tuple
void mynsdb::Part_Print(mynsdb::Part& row, algo::cstring& str) {
    algo::tempstr temp;
    str << "mynsdb.part";

    algo::Smallstr50_Print(row.part, temp);
    PrintAttrSpaceReset(str,"part", temp);

    i32_Print(row.amt, temp);
    PrintAttrSpaceReset(str,"amt", temp);

    algo::Comment_Print(row.comment, temp);
    PrintAttrSpaceReset(str,"comment", temp);
}

